(async () => {
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const KEEP = ['run_start','room_enter','room_start','room_cleared','reward_offer','draft_taken','draft_declined','path_offer','path_chosen','room_transition','shop_open','shop_purchase','currency_denied','shop_close','glint_gain','run_end','run_wiped','reward_forfeited','boss_spawn','boss_phase','boss_adds','victory','defeat'];
  const log = [];
  for (const t of KEEP) __echoes.on(t, (ev) => log.push(Object.assign({ t: ev.type, tk: ev.tick }, ev)));
  window.__log = log;
  const R = () => __echoes.cmd('runState');
  __echoes.cmd('startRun');
  await sleep(120);
  const trace = [];
  for (let g = 0; g < 60; g++) {
    const v = R();
    trace.push(v.room + '/' + v.mode + '/' + v.phase);
    if (v.phase === 'combat' && v.room === 8) break;
    if (v.phase === 'combat') { __echoes.cmd('clearRoom'); await sleep(120); }
    else if (v.phase === 'reward') { __echoes.cmd('draftTake'); await sleep(120); __echoes.cmd('closeSocket'); await sleep(60); }
    else if (v.phase === 'path') { __echoes.cmd('pathChoose', 0); await sleep(450); }
    else if (v.phase === 'shop') { break; }
    else if (v.phase === 'fade') { await sleep(200); }
    else break;
  }
  window.__trace = trace;
  return { trace, v: R() };
})()
